; Fuxoft Soundtrack IV (Frantisek Fuka, ZX Spectrum) for the SAPI-1 V (JPR-1V, RAM-1V, CGA-1V,
; MPH-1V) as a CP/M .COM. Made once from orig/fxs4.asm (generated by tools/mkdis.py), edited by hand
; since then; every change is marked SAPI: and says what the Spectrum did. The original lay at
; 744Ah-FFFFh; all its addresses are labels, so here it is assembled from 0103h.
; Hardware layer: platform.asm, generated data: tables.asm (tools/make_tables.py).
; Assembles with pasmo 0.5.3 (build.cmd).

	org 0100h
	jp sapi_init			; SAPI: CP/M start

; SAPI: the screen is drawn on the CGA-1V directly by platform.asm: the start screen, the line
; animation (plot_xor, draw_xor instead of ROM PLOT and DRAW), the VU meters (vu_cga) and the
; scroller (scroll_cga). The Spectrum screen code of the original is left out.
line_buf         equ LINE_BUF	; SAPI: was the printer buffer 5B00h, must start a page
sv_frames        equ frames	; SAPI: was FRAMES (5C78h), counted by the ROM interrupt

; ======================================================================
; CODE block of the original (744A-FFFF on the Spectrum)

