; Line animation, called from BASIC in a loop (RANDOMIZE USR 33890).
; Draws bouncing lines with the ROM DRAW, end points in the printer buffer.
; Returns on a key (or on SPACE only, when BASIC pokes CAh to lines_exit_jp:
; KEY-SCAN code + 1 = 21h).
lines:	ld hl,line_buf                   ; 8462
	xor a                                  ; 8465
	ld (lines_new),a                       ; 8466
	ld (lines_ptr),hl                      ; 8469
L846C:	ld (hl),a                        ; 846C
	inc l                                  ; 846D
	jr nz,L846C                            ; 846E
	call random                            ; 8470
	ld (hl),a                              ; 8473
	inc l                                  ; 8474
	call random                            ; 8475
	ld (hl),a                              ; 8478
	inc l                                  ; 8479
	call random                            ; 847A
	and 7Fh                                ; 847D
	ld (hl),a                              ; 847F
	inc l                                  ; 8480
	call random                            ; 8481
	and 7Fh                                ; 8484
	ld (hl),a                              ; 8486
lines_new_dir:	ld hl,lines_delta        ; 8487
	ld b,04h                               ; 848A
L848C:	call random                      ; 848C
	and 1Fh                                ; 848F
	srl a                                  ; 8491
	jr c,L8497                             ; 8493
	neg                                    ; 8495
L8497:	ld (hl),a                        ; 8497
	inc hl                                 ; 8498
	djnz L848C                             ; 8499
lines_loop:	ld hl,(lines_ptr)           ; 849B
	call draw_line                         ; 849E
	ld a,(lines_ptr)                       ; 84A1
	add a,0A0h                             ; 84A4
	ld l,a                                 ; 84A6
	ld h,high line_buf                     ; 84A7  SAPI: was 5Bh
	call draw_line                         ; 84A9
	ld hl,(lines_ptr)                      ; 84AC
	ld de,lines_delta                      ; 84AF
	call move_x                            ; 84B2
	call move_x                            ; 84B5
	call move_y                            ; 84B8
	call move_y                            ; 84BB
	ld (lines_ptr),hl                      ; 84BE
	ld hl,colours_1                        ; 84C1
lines_colour_ptr equ $-2
L84C4:	ld a,(hl)                        ; 84C4
	inc hl                                 ; 84C5
	or a                                   ; 84C6
	jr nz,L84CE                            ; 84C7
	ld hl,colours                          ; 84C9
	jr L84C4                               ; 84CC
L84CE:	ld (lines_colour_ptr),hl         ; 84CE
; SAPI: the Spectrum filled the attributes of rows 0-15 (5800h-59FFh) with A. Here the
; colour of those rows is one palette entry of the CGA-1V.
	call anim_colour                       ; 84D1
	call key_scan                          ; 84DF  SAPI: was ROM KEY-SCAN
	inc e                                  ; 84E2
	jp z,lines_key                         ; 84E3
	ld a,e                                 ; 84E6
	cp 21h                                 ; 84E7
lines_exit_jp:	jp exit_basic            ; 84E9  BASIC pokes C3h (jp) or CAh (jp z)
lines_after_key:	ld a,(lines_new)       ; 84EC
	or a                                   ; 84EF
	jp z,lines_loop                        ; 84F0
	xor a                                  ; 84F3
	ld (lines_new),a                       ; 84F4
	jp lines_new_dir                       ; 84F7
fill_page:	ld (hl),a                    ; 84FA
	inc l                                  ; 84FB
	jp nz,fill_page                        ; 84FC
	ret                                    ; 84FF
