; Interrupt work: a song key restarts that song, otherwise one player tick
; (3 ticks with ENTER held). The border is magenta during the tick.
frame:	call key_scan                    ; C000  SAPI: was ROM KEY-SCAN
	ld a,e                                 ; C003
select_song:	call song_for_key          ; C004
	ld de,song_hdr                         ; C007
	ld bc,0006h                            ; C00A
	ldir                                   ; C00D
	call set_noise_mask                    ; C00F
	call jp_init                           ; C012
	ret                                    ; C015
; HL = song header for KEY-SCAN code A; noise mask 0Fh for A-K, 1Fh for L-Z
song_for_key:	ld hl,noise_mask_val      ; C016
	ld (hl),0Fh                            ; C019
	cp 26h                                 ; C01B
	jr nz,LC023                            ; C01D
	ld hl,song_A                           ; C01F
	ret                                    ; C022
