	cp 21h                                 ; C107
	di                                     ; C109
	push af                                ; C10A
	call z,tick                            ; C10B
	pop af                                 ; C10E
	call z,tick                            ; C10F
	ret                                    ; C112
; SAPI: unused (73 zero bytes at C113h) left out
; USR 49500: start song A and the IM 2 interrupt, return to BASIC
start_music:	ld a,26h                   ; C15C
	jp select_song                         ; C15E
; Set the noise mask of command 8Dh, then stop the music (IM 1, AY silent)
set_noise_mask:	ld hl,noise_mask        ; C161
	ld (hl),1Fh                            ; C164  operand set by song_for_key
noise_mask_val   equ $-1
	jp jp_stop                             ; C166
	defb 00h,00h,00h,00h,00h,00h,00h       ; C169
; SAPI: the Spectrum went back to IM 1 (ROM interrupt only); here the interrupt keeps running
; and music_on = 0 stops the interrupt body
restore_im1:	di                         ; C170
	xor a                                  ; C171
	ld (music_on),a                        ; C172
	ret                                    ; C177
	defb 00h,00h,00h,00h,00h,00h,00h,00h   ; C178
; Interrupt body: VU meters, scroller, keys and music
isr_body:	nop                           ; C180
	nop                                    ; C181
	nop                                    ; C182
	nop                                    ; C183
	call vu_cga                            ; C184  SAPI: was vu_meters (Spectrum screen)
	call scroll_cga                        ; C187  SAPI: was scroller (Spectrum screen)
	jp frame                               ; C18A
; SAPI: unused (115 zero bytes at C18Dh) left out
; SAPI: no IM 2 vector table (C200h-C301h) and no gap after it
; Jump vectors
jp_init:	jp init_song                   ; C350
jp_stop:	jp stop_music                  ; C353
jp_tick:	jp tick                        ; C356
; Start the song in song_hdr and the IM 2 interrupt
init_song:	di                           ; C359
	ld hl,(song_hdr)                       ; C35A
	ld (chan_a),hl                         ; C35D
	ld hl,(LC837)                          ; C360
	ld (chan_b),hl                         ; C363
	ld hl,(LC839)                          ; C366
	ld (chan_c),hl                         ; C369
	ld a,01h                               ; C36C
	ld (LC462),a                           ; C36E
	ld (LC476),a                           ; C371
	ld (LC48A),a                           ; C374
	ld a,08h                               ; C377
	ld (LC463),a                           ; C379
	ld (LC477),a                           ; C37C
	ld (LC48B),a                           ; C37F
	ld hl,stack_b                          ; C382
	ld de,0020h                            ; C385
	ld (sp_a),hl                           ; C388
	add hl,de                              ; C38B
	ld (sp_b),hl                           ; C38C
	add hl,de                              ; C38F
	ld (sp_c),hl                           ; C390
	ld hl,0000h                            ; C393
	ld (LC46E),hl                          ; C396
	ld (LC482),hl                          ; C399
	ld (LC496),hl                          ; C39C
; SAPI: the pitch effect starts at 0000h on the Spectrum (ROM bytes, read by songs E, F and R)
	ld hl,rom_head
	ld (LC470),hl                          ; C39F
	ld (LC484),hl                          ; C3A2
	ld (LC498),hl                          ; C3A5
	xor a                                  ; C3A8
	ld (noise),a                           ; C3A9
; SAPI: the Spectrum set up IM 2 (I = C2h, jr at FFFFh, jp isr at FFF4h); here music_on = 1
; lets the interrupt of platform.asm call isr_body
	inc a
	ld (music_on),a
	ei                                     ; C3C2
	ret                                    ; C3C3
; SAPI: the IM 2 handler (C3C4h: di, saves registers, call isr_body, jp 0038h) is isr in
; platform.asm
; USR 50003: back to IM 1 and silence the AY
stop_music:	call restore_im1            ; C3D7
	ld a,0FFh                              ; C3DA
	ld d,07h                               ; C3DC
	call set_reg                           ; C3DE
	call ay_write                          ; C3E1
