	defw 00BDh                             ; C506
	defw 00B2h                             ; C508
	defw 00A8h                             ; C50A
	defw 009Fh                             ; C50C
	defw 0096h                             ; C50E
	defw 008Dh                             ; C510
	defw 0085h                             ; C512
	defw 007Eh                             ; C514
	defw 0077h                             ; C516
	defw 0070h                             ; C518
	defw 006Ah                             ; C51A
	defw 0064h                             ; C51C
	defw 005Eh                             ; C51E
	defw 0059h                             ; C520
	defw 0054h                             ; C522
	defw 004Fh                             ; C524
	defw 004Bh                             ; C526
	defw 0047h                             ; C528
	defw 0043h                             ; C52A
	defw 003Fh                             ; C52C
	defw 003Bh                             ; C52E
	defw 0038h                             ; C530
	defw 0035h                             ; C532
