; One player tick (50 Hz): three channels, then all AY registers
tick:	ld ix,chan_a                      ; C544
	ld hl,(sp_a)                           ; C548
	ld a,01h                               ; C54B
	call chan_tick                         ; C54D
	ld (sp_a),hl                           ; C550
	ld ix,chan_b                           ; C553
	ld hl,(sp_b)                           ; C557
	ld a,02h                               ; C55A
	call chan_tick                         ; C55C
	ld (sp_b),hl                           ; C55F
	ld ix,chan_c                           ; C562
	ld hl,(sp_c)                           ; C566
	ld a,03h                               ; C569
	call chan_tick                         ; C56B
	ld (sp_c),hl                           ; C56E
	ld a,(LC48B)                           ; C571
	rlca                                   ; C574
	ld b,a                                 ; C575
	ld a,(LC477)                           ; C576
	or b                                   ; C579
	rlca                                   ; C57A
	ld b,a                                 ; C57B
	ld a,(LC463)                           ; C57C
	or b                                   ; C57F
	ld d,07h                               ; C580
	call set_reg                           ; C582
; SAPI: the Spectrum wrote R13-R0 from ay_regs to the AY (OUT FFFDh, BFFDh); here the YM3812
; plays them (opl_update)
ay_write:	jp opl_update                 ; C585
set_reg:	ld bc,ay_regs                  ; C59B
	ld l,d                                 ; C59E
	ld h,00h                               ; C59F
	add hl,bc                              ; C5A1
	ld (hl),a                              ; C5A2
	ret                                    ; C5A3
chan_end:	ld (save_hl),sp               ; C5A4
	ld hl,(save_hl)                        ; C5A8
	ld sp,(save_sp)                        ; C5AB
	ret                                    ; C5AF
; Tick of one channel. IX = channel block, HL = its stack, A = channel 1-3
chan_tick:	ld (save_sp),sp              ; C5B0
	ld sp,hl                               ; C5B4
	ld (channel),a                         ; C5B5
	dec (ix+2)                             ; C5B8
	jp z,note_read                         ; C5BB
env_tick:	dec (ix+6)                    ; C5BE
	jr nz,fx_tick                          ; C5C1
env_read:	ld l,(ix+4)                   ; C5C3
	ld h,(ix+5)                            ; C5C6
