	cp 80h                                 ; C5CA
	jr nz,LC5DA                            ; C5CC
	inc hl                                 ; C5CE
	ld e,(hl)                              ; C5CF
	inc hl                                 ; C5D0
	ld d,(hl)                              ; C5D1
	ld (ix+4),e                            ; C5D2
	ld (ix+5),d                            ; C5D5
