	ld (ix+6),01h                          ; C5E3
	inc hl                                 ; C5E7
	jr LC5F3                               ; C5E8
LC5EA:	ld (ix+9),a                      ; C5EA
	inc hl                                 ; C5ED
	ld a,(hl)                              ; C5EE
	ld (ix+6),a                            ; C5EF
	inc hl                                 ; C5F2
LC5F3:	ld (ix+4),l                      ; C5F3
	ld (ix+5),h                            ; C5F6
fx_tick:	ld a,(ix+7)                    ; C5F9
