	ld l,(ix+12)                           ; C609
	ld h,(ix+13)                           ; C60C
fx_read:	ld a,(hl)                      ; C60F
	inc hl                                 ; C610
	ld (ix+12),l                           ; C611
	ld (ix+13),h                           ; C614
	cp 80h                                 ; C617
	jr nz,LC621                            ; C619
	ld a,(hl)                              ; C61B
	inc hl                                 ; C61C
	ld h,(hl)                              ; C61D
	ld l,a                                 ; C61E
	jr fx_read                             ; C61F
LC621:	cp 82h                           ; C621
	jp nz,LC62D                            ; C623
	set 3,(ix+14)                          ; C626
	jp fx_read                             ; C62A
LC62D:	cp 83h                           ; C62D
	jp nz,LC639                            ; C62F
	res 3,(ix+14)                          ; C632
	jp fx_read                             ; C636
LC639:	cp 84h                           ; C639
	jp nz,LC649                            ; C63B
	ld a,09h                               ; C63E
	xor (ix+3)                             ; C640
	ld (ix+3),a                            ; C643
	jp fx_read                             ; C646
LC649:	bit 3,(ix+14)                    ; C649
	jp z,LC66B                             ; C64D
	add a,(ix+18)                          ; C650
	ld (ix+18),a                           ; C653
	dec a                                  ; C656
	add a,a                                ; C657
	ld e,a                                 ; C658
	ld d,00h                               ; C659
	ld hl,tone_table                       ; C65B
	add hl,de                              ; C65E
	ld a,(hl)                              ; C65F
	ld (ix+7),a                            ; C660
	inc hl                                 ; C663
	ld a,(hl)                              ; C664
	ld (ix+8),a                            ; C665
	jp chan_out                            ; C668
LC66B:	ld e,a                           ; C66B
	ld d,00h                               ; C66C
	ld l,(ix+7)                            ; C66E
	ld h,(ix+8)                            ; C671
	and 80h                                ; C674
	jp z,LC67B                             ; C676
	ld d,0FFh                              ; C679
LC67B:	add hl,de                        ; C67B
	ld (ix+7),l                            ; C67C
	ld (ix+8),h                            ; C67F
chan_out:	ld a,(noise)                  ; C682
	ld d,06h                               ; C685
