	ld a,(channel)                         ; C68E
	add a,07h                              ; C691
	ld d,a                                 ; C693
	ld a,(ix+7)                            ; C694
	or (ix+8)                              ; C697
	jr z,LC69F                             ; C69A
	ld a,(ix+9)                            ; C69C
LC69F:	call set_reg                     ; C69F
	ld a,(channel)                         ; C6A2
	dec a                                  ; C6A5
	add a,a                                ; C6A6
	ld d,a                                 ; C6A7
	ld a,(ix+7)                            ; C6A8
	call set_reg                           ; C6AB
	inc d                                  ; C6AE
	ld a,(ix+8)                            ; C6AF
	call set_reg                           ; C6B2
	jp chan_end                            ; C6B5
store_ptr:	ld (ix+0),l                  ; C6B8
	ld (ix+1),h                            ; C6BB
	ret                                    ; C6BE
; Next item of the note stream (note, rest or command)
note_read:	ld l,(ix+0)                  ; C6BF
	ld h,(ix+1)                            ; C6C2
	ld a,(hl)                              ; C6C5
	inc hl                                 ; C6C6
	call store_ptr                         ; C6C7
