	add a,(ix+15)                          ; C6D5
	ld (ix+18),a                           ; C6D8
	res 3,(ix+14)                          ; C6DB
	dec a                                  ; C6DF
	add a,a                                ; C6E0
	ld e,a                                 ; C6E1
	ld d,00h                               ; C6E2
	ld hl,tone_table                       ; C6E4
	add hl,de                              ; C6E7
	ld e,(hl)                              ; C6E8
	inc hl                                 ; C6E9
